import sys

DIGITS = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"


def to_base36(value: int, width: int) -> str:
    """Convert an integer to a zero-padded uppercase base-36 string."""
    result = []
    for _ in range(width):
        result.append(DIGITS[value % 36])
        value //= 36
    return "".join(reversed(result))


def next_suffix(current: str) -> str:
    """Given a 4-character base-36 suffix, return the next one."""
    return to_base36(int(current, 36) + 1, len(current))


