    with open("ids.txt") as f:
        lines = [line.rstrip("\n") for line in f if line.strip()]

    if not lines:
        print("ORD-0000")
        return

    last_id = lines[-1]
    suffix = last_id[4:]  # strip "ORD-"
    print(f"ORD-{next_suffix(suffix)}")


if __name__ == "__main__":
    main()

