#!/usr/bin/env python3
import sys

BASE36 = '0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ'


def base36_decode(s: str) -> int:
    """Decode a base36 string to an integer."""
    n = 0
    for ch in s:
        n = n * 36 + BASE36.index(ch.upper())
    return n


def base36_encode(n: int, length: int = 4) -> str:
    """Encode an integer as a zero-padded base36 string of the given length."""
    digits = []
    for _ in range(length):
        digits.append(BASE36[n % 36])
        n //= 36
    return ''.join(reversed(digits))


def main():
    try:
        with open('ids.txt') as f:
            lines = f.readlines()
    except FileNotFoundError:
        print('ids.txt not found', file=sys.stderr)
        sys.exit(1)

    # Find the last non-empty line with a valid ORD-XXXX id
    last_id = None
    for line in reversed(lines):
        line = line.strip()
        if line.startswith('ORD-') and len(line) == 8:
            last_id = line
            break

    if last_id is None:
        print('No valid ORD-XXXX id found in ids.txt', file=sys.stderr)
        sys.exit(1)

    suffix = last_id[4:]   # e.g. '243G'
    num = base36_decode(suffix)
    next_num = num + 1
    next_suffix = base36_encode(next_num, length=4)
    print(f'ORD-{next_suffix}')


if __name__ == '__main__':
    main()

