"""Merge all CSV files under data/ into all.csv.

Files are processed in sorted filename order. Rows within each file are kept
in their original order. The output has a single header line: id,name,qty.
"""

import csv
import os

DATA_DIR = "data"
OUTPUT = "all.csv"


def main() -> None:
    csv_files = sorted(
        os.path.join(DATA_DIR, f)
        for f in os.listdir(DATA_DIR)
        if f.endswith(".csv")
    )

    header_written = False

    with open(OUTPUT, "w", newline="") as out_f:
        writer = None
        for path in csv_files:
            with open(path, newline="") as in_f:
                reader = csv.reader(in_f)
                for row in reader:
                    if not header_written:
                        writer = csv.writer(out_f)
                        writer.writerow(row)
                        header_written = True
                    else:
                        writer.writerow(row)


if __name__ == "__main__":
