"""Read events.jsonl, remove duplicates by event_id (keep last), write deduped.jsonl."""

import json


def main() -> None:
    seen: dict[str, dict] = {}
    with open("events.jsonl", encoding="utf-8") as f:
        for line in f:
            line = line.strip()
            if not line:
                continue
            event = json.loads(line)
            seen[event["event_id"]] = event  # last occurrence wins

    with open("deduped.jsonl", "w", encoding="utf-8") as out:
        for event in seen.values():
            out.write(json.dumps(event, ensure_ascii=False) + "\n")


if __name__ == "__main__":
    main()

