#!/usr/bin/env python3
import json

seen = set()
with open("events.jsonl") as f_in, open("deduped.jsonl", "w") as f_out:
    for line in f_in:
        line = line.rstrip("\n")
        if not line:
            continue
        event = json.loads(line)
        eid = event.get("event_id")
        if eid not in seen:
            seen.add(eid)
            f_out.write(line + "\n")

