#!/usr/bin/env python3
"""Generate manifest.json with SHA-256 digests for all files under release/."""

import hashlib
import json
from pathlib import Path

RELEASE_DIR = Path("release")
MANIFEST_PATH = Path("manifest.json")


def sha256_digest(filepath: Path) -> str:
    """Return the SHA-256 hex digest of a file."""
    h = hashlib.sha256()
    with filepath.open("rb") as f:
        for chunk in iter(lambda: f.read(8192), b""):
            h.update(chunk)
    return h.hexdigest()


def main() -> None:
    manifest = {}

    # Walk the release/ tree and collect all regular files.
    for path in sorted(RELEASE_DIR.rglob("*")):
        if path.is_file():
            # Store the path relative to the repository root
            rel_path = str(path)
            manifest[rel_path] = sha256_digest(path)

    with MANIFEST_PATH.open("w") as f:
        json.dump(manifest, f, indent=2)
        f.write("\n")

    print(f"manifest.json written with {len(manifest)} entries.")


if __name__ == "__main__":
    main()

