"""Generate manifest.json for files under release/.

Writes a JSON object mapping each file's path (relative to the repository
root) to its SHA-256 hex digest, so the deploy target can verify what it
received.
"""

import hashlib
import json
from pathlib import Path

RELEASE_DIR = Path(__file__).resolve().parent / "release"
MANIFEST_PATH = Path(__file__).resolve().parent / "manifest.json"


def sha256_hex(path: Path) -> str:
    digest = hashlib.sha256()
    with path.open("rb") as f:
        for chunk in iter(lambda: f.read(65536), b""):
            digest.update(chunk)
    return digest.hexdigest()


def main() -> None:
    manifest = {}
    for path in sorted(RELEASE_DIR.rglob("*")):
        if path.is_file():
            rel_path = path.relative_to(RELEASE_DIR.parent).as_posix()
            manifest[rel_path] = sha256_hex(path)
    MANIFEST_PATH.write_text(json.dumps(manifest, indent=2) + "\n")


if __name__ == "__main__":
    main()

