#!/usr/bin/env python3
"""Generate manifest.json with SHA-256 hex digests for all files under release/."""

import hashlib
import json
import os

RELEASE_DIR = "release"
MANIFEST_FILE = "manifest.json"


def sha256_hex(filepath: str) -> str:
    """Compute the SHA-256 hex digest of a file."""
    h = hashlib.sha256()
    with open(filepath, "rb") as f:
        while True:
            chunk = f.read(65536)
            if not chunk:
                break
            h.update(chunk)
    return h.hexdigest()


def main() -> None:
    manifest = {}

    for dirpath, _dirnames, filenames in os.walk(RELEASE_DIR):
        for filename in filenames:
            full_path = os.path.join(dirpath, filename)
            # Use forward-slash paths relative to repository root
            rel_path = os.path.relpath(full_path, start=".").replace(os.sep, "/")
            manifest[rel_path] = sha256_hex(full_path)

    with open(MANIFEST_FILE, "w") as f:
        json.dump(manifest, f, indent=2)
        f.write("\n")

    print(f"Written {MANIFEST_FILE} with {len(manifest)} entries.")


if __name__ == "__main__":
    main()

