#!/usr/bin/env python3
"""Generate manifest.json: maps each file under release/ to its SHA-256 hex digest."""

import hashlib
import json
from pathlib import Path

RELEASE_DIR = Path("release")
MANIFEST_PATH = Path("manifest.json")


def sha256_digest(path: Path) -> str:
    """Return the lowercase hex SHA-256 digest of the file at *path*."""
    h = hashlib.sha256()
    with open(path, "rb") as f:
        for chunk in iter(lambda: f.read(65536), b""):
            h.update(chunk)
    return h.hexdigest()


def main() -> None:
    manifest: dict[str, str] = {}

    # Walk release/ in sorted order for deterministic output.
    for child in sorted(RELEASE_DIR.rglob("*")):
        if child.is_file():
            rel = child.as_posix()  # forward slashes in the key
            manifest[rel] = sha256_digest(child)

    with open(MANIFEST_PATH, "w") as f:
        json.dump(manifest, f, indent=2, sort_keys=True)
        f.write("\n")

    print(f"Wrote {len(manifest)} entries to {MANIFEST_PATH}")


if __name__ == "__main__":
    main()

