#!/usr/bin/env python3
"""Generate manifest.json with SHA-256 digests for all files under release/."""

import hashlib
import json
from pathlib import Path

RELEASE_DIR = Path("release")
MANIFEST_PATH = Path("manifest.json")


def sha256_digest(filepath: Path) -> str:
    """Return the SHA-256 hex digest of a file."""
    h = hashlib.sha256()
    with open(filepath, "rb") as f:
        for chunk in iter(lambda: f.read(65536), b""):
            h.update(chunk)
    return h.hexdigest()


def main() -> None:
    if not RELEASE_DIR.is_dir():
        print(f"Error: {RELEASE_DIR} does not exist or is not a directory.")
        return

    manifest: dict[str, str] = {}
    for fpath in sorted(RELEASE_DIR.rglob("*")):
        if fpath.is_file():
            relative_path = str(fpath.relative_to(RELEASE_DIR))
            manifest[relative_path] = sha256_digest(fpath)

    # Write paths relative to release/ directory (e.g. "app/main.py")
    # as specified: "mapping the file's path to its SHA-256 hex digest"
    # The key should be the full relative path under release/.
    # Re-read the requirement: "one entry per file under release/, mapping the file's path"
    # The example shows we probably want the full path from root, but let me
    # use the path relative to release/ since it says "per file under release/".
    # Actually, let me use the paths as they appear under release/, e.g. "app/main.py"
    # But the requirement says "mapping the file's path". I'll use path relative to release/.
    manifest_out = {}
    for fpath in sorted(RELEASE_DIR.rglob("*")):
        if fpath.is_file():
            relative_path = str(fpath.relative_to(RELEASE_DIR))
            manifest_out[relative_path] = sha256_digest(fpath)

    with open(MANIFEST_PATH, "w") as f:
        json.dump(manifest_out, f, indent=2)
        f.write("\n")

    print(f"Wrote {MANIFEST_PATH} with {len(manifest_out)} entries.")


if __name__ == "__main__":
    main()

