"""Rotate entries from app.log to archive.log.

Usage: python rotate.py AS_OF

AS_OF is a Unix timestamp in integer seconds. Every line of app.log starts with a
timestamp formatted YYYY-MM-DD HH:MM:SS followed by a message. Entries whose
timestamp is strictly older than 7 days before AS_OF are moved to archive.log
(appended, preserving order), and app.log is rewritten with the remaining entries
in their original order.
"""

import sys
from datetime import datetime, timezone, timedelta


def parse_line_timestamp(line: str) -> datetime | None:
    """Try to parse the leading 'YYYY-MM-DD HH:MM:SS' from a line."""
    if len(line) < 19:
        return None
    try:
        return datetime.strptime(line[:19], "%Y-%m-%d %H:%M:%S").replace(
            tzinfo=timezone.utc
        )
    except ValueError:
        return None


def main() -> None:
    if len(sys.argv) != 2:
        print(f"Usage: {sys.argv[0]} AS_OF", file=sys.stderr)
        sys.exit(1)

    try:
        as_of = int(sys.argv[1])
    except ValueError:
        print(f"Error: AS_OF must be an integer (got {sys.argv[1]!r})", file=sys.stderr)
        sys.exit(1)

    cutoff = as_of - 7 * 24 * 60 * 60  # 7 days in seconds

    try:
        with open("app.log") as f:
            lines = f.readlines()
    except FileNotFoundError:
        print("Error: app.log not found", file=sys.stderr)
        sys.exit(1)

    keep: list[str] = []
    archive: list[str] = []

    for line in lines:
        # Preserve empty or malformed lines — don't drop data
        ts = parse_line_timestamp(line)
        if ts is not None:
            line_ts = int(ts.timestamp())
            if line_ts < cutoff:
                archive.append(line)
            else:
                keep.append(line)
        else:
            # Can't determine age; keep in app.log
            keep.append(line)

    with open("app.log", "w") as f:
        f.writelines(keep)

    if archive:
        with open("archive.log", "a") as f:
            f.writelines(archive)

    print(
        f"Moved {len(archive)} entries to archive.log, "
        f"{len(keep)} entries remain in app.log"
    )


if __name__ == "__main__":
    main()

