#!/usr/bin/env python3
"""Rotate app.log: move entries older than 7 days before AS_OF into archive.log."""

import sys
import os
from datetime import datetime, timedelta, timezone


def parse_ts(line: str):
    """Try to parse a leading YYYY-MM-DD HH:MM:SS timestamp from line.
    Returns a datetime (naive, treated as UTC) or None."""
    if len(line) < 19:
        return None
    try:
        return datetime.strptime(line[:19], "%Y-%m-%d %H:%M:%S")
    except ValueError:
        return None


def main():
    if len(sys.argv) != 2:
        print("Usage: python rotate.py AS_OF", file=sys.stderr)
        sys.exit(1)

    try:
        as_of = int(sys.argv[1])
    except ValueError:
        print("AS_OF must be an integer Unix timestamp.", file=sys.stderr)
        sys.exit(1)

    as_of_dt = datetime.fromtimestamp(as_of, tz=timezone.utc)
    cutoff = as_of_dt - timedelta(days=7)

    script_dir = os.path.dirname(os.path.abspath(__file__))
    app_log = os.path.join(script_dir, "app.log")
    archive_log = os.path.join(script_dir, "archive.log")

    if not os.path.isfile(app_log):
        print("app.log not found.", file=sys.stderr)
        sys.exit(1)

    with open(app_log, "r") as f:
        lines = f.readlines()

    keep = []
    archive = []

    for line in lines:
        ts = parse_ts(line)
        if ts is not None:
            # Treat naive datetime as UTC
            line_dt = ts.replace(tzinfo=timezone.utc)
            if line_dt < cutoff:
                archive.append(line)
            else:
                keep.append(line)
        else:
            # Lines without a parseable timestamp stay in app.log
            keep.append(line)

    # Append to archive.log (create if not exists)
    with open(archive_log, "a") as f:
        for line in archive:
            f.write(line)

    # Rewrite app.log
    with open(app_log, "w") as f:
        for line in keep:
            f.write(line)

    print(f"OK: {len(archive)} entries archived, {len(keep)} entries remain in app.log.")


if __name__ == "__main__":
    main()

